55:       if(tile===T.STAIR){ctx.fillStyle='#c2ab69';ctx.globalAlpha=.7;ctx.beginPath();ctx.arc(px+TILE/2,py+TILE/2,8,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle='#ead494';ctx.lineWidth=1.5;for(let i=0;i<3;i++){ctx.beginPath();ctx.moveTo(px+8,py+10+i*4);ctx.lineTo(px+TILE-8,py+10+i*4);ctx.stroke()}ctx.fillStyle='#fff0bb';ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText('↓',px+TILE/2,py+TILE/2+3)}
