57:       if(tile===T.SHRINE){ctx.fillStyle='#685d3c';ctx.fillRect(px+14,py+14,4,10);ctx.fillStyle='#d3bd79';ctx.beginPath();ctx.arc(px+TILE/2,py+12,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffedb4';ctx.beginPath();ctx.arc(px+TILE/2,py+12,2,0,Math.PI*2);ctx.fill()}
58:       if(tile===T.DOOR){ctx.fillStyle='#70583b';ctx.fillRect(px+9,py+5,14,24);ctx.fillStyle='#c1a265';ctx.fillRect(px+10,py+6,12,22);ctx.fillStyle='#59452e';ctx.fillRect(px+12,py+8,8,18);ctx.fillStyle='#e8cc80';ctx.fillRect(px+18,py+18,2,2)}
