67:   function drawPlayer(x,y){ctx.fillStyle='#c9a95e';ctx.globalAlpha=.25;ctx.beginPath();ctx.arc(x+TILE/2,y+TILE/2,13,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#4e4230';ctx.beginPath();ctx.moveTo(x+10,y+24);ctx.lineTo(x+14,y+11);ctx.lineTo(x+18,y+9);ctx.lineTo(x+22,y+13);ctx.lineTo(x+25,y+25);ctx.fill();ctx.fillStyle='#d4c49d';ctx.beginPath();ctx.arc(x+18,y+11,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#94876c';ctx.fillRect(x+12,y+15,12,10);ctx.fillStyle='#e5cb83';ctx.fillRect(x+17,y+14,2,4);ctx.fillStyle='#eee4c6';ctx.fillRect(x+19,y+10,2,2)}
68:   function drawEnemy(x,y,e){if(e.boss){ctx.fillStyle='rgba(190,72,61,.25)';ctx.beginPath();ctx.arc(x+TILE/2,y+TILE/2,15,0,Math.PI*2);ctx.fill();ctx.fillStyle='#542f35';ctx.beginPath();ctx.moveTo(x+6,y+27);ctx.lineTo(x+9,y+13);ctx.lineTo(x+18,y+6);ctx.lineTo(x+27,y+13);ctx.lineTo(x+30,y+27);ctx.closePath();ctx.fill();ctx.fillStyle='#c2b49a';ctx.beginPath();ctx.arc(x+18,y+13,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ed765c';ctx.fillRect(x+14,y+12,3,2);ctx.fillRect(x+20,y+12,3,2);ctx.fillStyle='#d2b666';ctx.fillRect(x+8,y+5,20,3);ctx.fillStyle='#d27462';ctx.fillRect(x+8,y+5,20*e.hp/e.maxHp,3);return}const elite=e.kind==='elite';ctx.fillStyle=elite?'rgba(181,93,69,.19)':'rgba(170,170,145,.13)';ctx.beginPath();ctx.arc(x+TILE/2,y+TILE/2,12,0,Math.PI*2);ctx.fill();if(e.name.includes('쥐')){ctx.fillStyle='#96907e';ctx.beginPath();ctx.ellipse(x+18,y+19,7,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d8b27f';ctx.beginPath();ctx.arc(x+24,y+18,3.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b84e46';ctx.fillRect(x+25,y+17,2,2);ctx.beginPath();ctx.moveTo(x+12,y+16);ctx.lineTo(x+9,y+10);ctx.lineTo(x+16,y+14);ctx.fill()}else{ctx.fillStyle=elite?'#765148':'#71756e';ctx.beginPath();ctx.moveTo(x+9,y+26);ctx.lineTo(x+12,y+14);ctx.lineTo(x+14,y+10);ctx.lineTo(x+21,y+10);ctx.lineTo(x+25,y+17);ctx.lineTo(x+26,y+26);ctx.fill();ctx.fillStyle='#bfb59a';ctx.beginPath();ctx.arc(x+18,y+12,5,0,Math.PI*2);ctx.fill();ctx.fillStyle=elite?'#e77d5c':'#d7c89b';ctx.fillRect(x+15,y+12,2,2);ctx.fillRect(x+20,y+12,2,2);ctx.fillStyle='#9c8b65';ctx.fillRect(x+11,y+20,14,2)}if(e.hp<e.maxHp){ctx.fillStyle='#24241f';ctx.fillRect(x+8,y+5,20,3);ctx.fillStyle='#d27462';ctx.fillRect(x+8,y+5,20*e.hp/e.maxHp,3)}}
69:   function updateUI(){ui('hpText').textContent=`${state.hp} / ${state.maxHp}`;ui('hpBar').style.width=`${100*state.hp/state.maxHp}%`;ui('levelText').textContent=`Lv. ${state.level}`;const need=state.level*8;ui('xpText').textContent=`${state.xp} / ${need}`;ui('xpBar').style.width=`${100*state.xp/need}%`;ui('pathwayText').textContent=`광대 경로 · 서열 ${Math.max(7,10-state.level)}`;ui('skillBtn').disabled=state.skillUsed;ui('skillBtn').textContent=state.skillUsed?'사용 완료':'사용';ui('skillHint').textContent=state.skillUsed?'다음 층에서 다시 사용할 수 있다.':'한 층에 한 번, 적의 움직임을 멈춘다.';const boss=state.enemies.find(e=>e.boss);ui('bossStatus').hidden=state.floor<3;ui('bossStatus').textContent=boss?`최종 관문 · 검은 사도  ${boss.hp} / ${boss.maxHp}`:'검은 사도가 쓰러졌다 · 계단 봉인 해제';ui('potionCount').textContent=state.potions;ui('mobilePotionCount').textContent=state.potions;ui('bombCount').textContent=state.bombs;ui('scrollCount').textContent=state.scrolls;ui('goldCount').textContent=state.gold;ui('turnText').textContent=`턴 ${state.turn}`;ui('positionText').textContent=`좌표 ${String(state.player.x+1).padStart(2,'0')}·${String(state.player.y+1).padStart(2,'0')}`;ui('floorNum').textContent=`층 ${String(state.floor).padStart(2,'0')}`;ui('runNum').textContent=String(state.run).padStart(2,'0');ui('enemyCount').textContent=state.enemies.filter(e=>state.visible.has(key(e.x,e.y))).length;const explored=state.seen.size/(SIZE*SIZE-36);const pct=Math.min(100,Math.round(explored*100));ui('questProgress').style.width=`${pct}%`;ui('questCount').textContent=`탐험 ${pct}%`;ui('objectiveTitle').textContent=state.floor>=3?'검은 사도를 물리쳐라':'회랑을 통과하라';ui('objectiveText').textContent=state.floor>=3?(state.enemies.some(e=>e.boss)?'계단을 지키는 사도를 쓰러뜨리고 봉인을 풀어라.':'봉인이 풀렸다. 계단으로 내려가 기억을 마주하라.'):'아래층으로 가는 계단을 찾아라.';ui('floorName').textContent=state.floor===1?'잊힌 회랑':state.floor===2?'속삭임의 납골당':'왕의 기억';}
70:   function damagePlayer(amount,source='적'){state.hp=Math.max(0,state.hp-amount);log(`${source}의 공격! 생명력 ${amount} 감소.`, 'warn');if(state.hp<=0)endRun(false)}
71:   function attack(enemy){const dmg=4+Math.floor(Math.random()*4)+(state.level-1)*2;enemy.hp-=dmg;state.turn++;log(`잿빛 검으로 ${enemy.name}을(를) 베었다. (${dmg})`, 'good');if(enemy.hp<=0){state.enemies=state.enemies.filter(e=>e!==enemy);state.xp+=enemy.boss?12:enemy.kind==='elite'?5:3;state.gold+=enemy.boss?15:enemy.kind==='elite'?5:2;state.kills++;log(enemy.boss?'검은 사도가 무너졌다. 계단의 봉인이 풀렸다!':`${enemy.name}을(를) 쓰러뜨렸다. 은화와 경험치를 얻었다.`, 'gold');checkLevel()}else{enemy.awake=true;enemyFlash()};enemyTurns();updateVisibility();draw()}
72:   function enemyFlash(){canvas.classList.remove('hit');void canvas.offsetWidth;canvas.classList.add('hit');setTimeout(()=>canvas.classList.remove('hit'),160)}
73:   function checkLevel(){let raised=false;while(state.xp>=state.level*8){state.xp-=state.level*8;state.level++;state.maxHp+=5;state.hp=Math.min(state.maxHp,state.hp+8);raised=true}if(raised){log(`레벨 상승! Lv. ${state.level} · 생명력이 회복되었다.`, 'gold');toast(`레벨 상승! Lv. ${state.level}`)}}
74:   function enemyTurns(){for(const e of [...state.enemies]){if(e.stunned){e.stunned--;continue}if(!e.awake&&Math.abs(e.x-state.player.x)+Math.abs(e.y-state.player.y)>5)continue;e.awake=true;const dist=Math.abs(e.x-state.player.x)+Math.abs(e.y-state.player.y);if(dist===1){damagePlayer(e.damage,e.name);if(state.gameOver)return;continue}let candidates=[[e.x+Math.sign(state.player.x-e.x),e.y],[e.x,e.y+Math.sign(state.player.y-e.y)]];if(Math.random()<.5)candidates.reverse();for(const [x,y] of candidates){if((x!==state.player.x||y!==state.player.y)&&isWalkable(x,y)&&state.map[y][x]===T.FLOOR){e.x=x;e.y=y;break}}}updateVisibility()}
75:   function step(dx,dy){if(state.gameOver||state.won)return;const x=state.player.x+dx,y=state.player.y+dy;if(!inBounds(x,y))return;const enemy=enemyAt(x,y);if(enemy){attack(enemy);return}const tile=state.map[y][x];if(tile===T.WALL){toast('벽이 길을 막고 있다.');return}if(tile===T.WATER){toast('깊은 물이라 건널 수 없다.');return}if(tile===T.STAIR){descend();return}if(tile===T.CHEST){openChest(x,y);return}if(tile===T.SHRINE){useShrine(x,y);return}state.player={x,y};state.turn++;const item=state.items.find(i=>i.x===x&&i.y===y);if(item){state.items=state.items.filter(i=>i!==item);if(item.type==='potion'){state.potions++;log('바닥에서 회복 물약을 주웠다.','good')}else{state.gold+=item.amount;log(`은화 ${item.amount}개를 주웠다.`,'gold')}}enemyTurns();updateVisibility();draw()}
76:   function openChest(x,y){const bonus=5+Math.floor(Math.random()*9);state.gold+=bonus;state.potions++;state.map[y][x]=T.FLOOR;state.chests=state.chests.filter(c=>c.x!==x||c.y!==y);state.turn++;log(`낡은 상자를 열었다. 은화 ${bonus}개와 물약을 발견했다!`,'gold');toast('상자를 열었다');enemyTurns();draw()}
77:   function useShrine(x,y){state.map[y][x]=T.FLOOR;state.shrine=null;state.hp=Math.min(state.maxHp,state.hp+12);state.turn++;log('낡은 제단에 기도했다. 생명력이 회복된다.','good');toast('제단이 희미하게 빛난다');enemyTurns();draw()}
78:   function descend(){if(state.floor>=3&&state.enemies.some(e=>e.boss)){toast('검은 사도가 계단을 봉인하고 있다.');return}if(state.floor>=3){state.won=true;state.turn++;log('마침내 왕의 기억을 되찾았다.','gold');draw();setTimeout(()=>showEnd(true),400);return}state.floor++;state.turn++;state.hp=Math.min(state.maxHp,state.hp+5);generateFloor();const floorName=state.floor===2?'속삭임의 납골당':'왕의 기억';log(`계단을 내려왔다. ${floorName}에 도착했다.`,'gold');toast(`층 ${String(state.floor).padStart(2,'0')} · 새로운 영역`);draw()}
79:   function useSkill(){if(state.gameOver||state.won)return;if(state.skillUsed){toast('이 층에서 운명 엿보기를 이미 사용했다.');return}state.skillUsed=true;for(let y=0;y<SIZE;y++)for(let x=0;x<SIZE;x++)state.seen.add(key(x,y));let caught=0;for(const e of state.enemies){if(Math.abs(e.x-state.player.x)+Math.abs(e.y-state.player.y)<=4){e.stunned=1;e.awake=true;caught++}}state.turn++;log(caught?`운명의 실을 읽었다. 주변의 적 ${caught}마리가 잠시 멈칫한다.`:'운명의 실을 읽었다. 잊힌 회랑의 지도가 드러난다.','gold');enemyTurns();updateVisibility();draw()}
80:   function usePotion(){if(state.potions<=0){toast('회복 물약이 없다.');return}if(state.hp===state.maxHp){toast('생명력이 이미 가득하다.');return}state.potions--;const healed=Math.min(12,state.maxHp-state.hp);state.hp+=healed;state.turn++;log(`회복 물약을 마셨다. 생명력 ${healed} 회복.`,'good');enemyTurns();draw()}
81:   function useBomb(){if(state.bombs<=0){toast('연막 폭탄이 없다.');return}state.bombs--;let hit=0;state.enemies=state.enemies.filter(e=>{if(Math.abs(e.x-state.player.x)<=2&&Math.abs(e.y-state.player.y)<=2){hit++;state.xp+=2;return false}return true});state.turn++;log(hit?`연막 폭탄이 터졌다. 적 ${hit}마리가 사라졌다.`:'연막 폭탄을 던졌다. 가까이에 적이 없다.',hit?'good':'');checkLevel();enemyTurns();draw()}
