71:   function updateUI(){ui('hpText').textContent=`${state.hp} / ${state.maxHp}`;ui('hpBar').style.width=`${100*state.hp/state.maxHp}%`;ui('levelText').textContent=`Lv. ${state.level}`;const need=state.level*8;ui('xpText').textContent=`${state.xp} / ${need}`;ui('xpBar').style.width=`${100*state.xp/need}%`;ui('pathwayText').textContent=`광대 경로 · 서열 ${Math.max(7,10-state.level)}`;ui('skillBtn').disabled=state.skillUsed;ui('skillBtn').textContent=state.skillUsed?'사용 완료':'사용';ui('skillHint').textContent=state.skillUsed?'다음 층에서 다시 사용할 수 있다.':'한 층에 한 번, 적의 움직임을 멈춘다.';const boss=state.enemies.find(e=>e.boss);ui('bossStatus').hidden=state.floor<3;ui('bossStatus').textContent=boss?`최종 관문 · 검은 사도  ${boss.hp} / ${boss.maxHp}`:'검은 사도가 쓰러졌다 · 계단 봉인 해제';ui('potionCount').textContent=state.potions;ui('mobilePotionCount').textContent=state.potions;ui('bombCount').textContent=state.bombs;ui('scrollCount').textContent=state.scrolls;ui('goldCount').textContent=state.gold;ui('turnText').textContent=`턴 ${state.turn}`;ui('positionText').textContent=`좌표 ${String(state.player.x+1).padStart(2,'0')}·${String(state.player.y+1).padStart(2,'0')}`;ui('floorNum').textContent=`층 ${String(state.floor).padStart(2,'0')}`;ui('runNum').textContent=String(state.run).padStart(2,'0');ui('enemyCount').textContent=state.enemies.filter(e=>state.visible.has(key(e.x,e.y))).length;const explored=state.seen.size/(SIZE*SIZE-36);const pct=Math.min(100,Math.round(explored*100));ui('questProgress').style.width=`${pct}%`;ui('questCount').textContent=`탐험 ${pct}%`;ui('objectiveTitle').textContent=state.floor>=3?'검은 사도를 물리쳐라':'회랑을 통과하라';ui('objectiveText').textContent=state.floor>=3?(state.enemies.some(e=>e.boss)?'계단을 지키는 사도를 쓰러뜨리고 봉인을 풀어라.':'봉인이 풀렸다. 계단으로 내려가 기억을 마주하라.'):'아래층으로 가는 계단을 찾아라.';ui('floorName').textContent=state.floor===1?'잊힌 회랑':state.floor===2?'속삭임의 납골당':'왕의 기억';}
